import React from 'react';
import { Box, Paper, Typography, Link } from '@mui/material';
import cityIndex from '../../config/cityIndex.json';

// Links to the static city prayer-time pages (/prayer-times/<country>/<city>/),
// generated by scripts/city-pages/build.mjs. cityIndex.json is a small summary
// made by make-list.mjs (the full list of 500 stays out of the app bundle).
// Plain links: those pages are not React routes.
const TOP = [...cityIndex.countries].sort((a, b) => b.count - a.count).slice(0, 12);
const TOTAL = cityIndex.countries.reduce((n, c) => n + c.count, 0);

const CityDirectory = () => (
    <Paper component="section" elevation={0} sx={{ mt: 4, p: { xs: 2, md: 3 }, border: 1, borderColor: 'divider', borderRadius: 2 }}>
        <Typography variant="h5" component="h2" color="primary" gutterBottom>
            Prayer times by city
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            Today's times, monthly timetables with Hijri dates and the Qibla direction for {TOTAL} cities in{' '}
            {cityIndex.countries.length} countries.
        </Typography>
        <Box sx={{ display: 'grid', gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', md: 'repeat(3, 1fr)' }, gap: 3 }}>
            {TOP.map((country) => (
                <Box key={country.cc}>
                    <Link href={`/prayer-times/${country.cc}/`} underline="hover" sx={{ fontWeight: 600 }}>
                        {country.name}
                    </Link>
                    <Typography variant="body2" sx={{ mt: 0.5, lineHeight: 1.9 }}>
                        {country.top.map((c, i) => (
                            <React.Fragment key={c.slug}>
                                {i > 0 && ' · '}
                                <Link href={`/prayer-times/${country.cc}/${c.slug}/`} underline="hover" color="text.primary">
                                    {c.name}
                                </Link>
                            </React.Fragment>
                        ))}
                        {country.count > country.top.length && (
                            <>
                                {' · '}
                                <Link href={`/prayer-times/${country.cc}/`} underline="hover">
                                    all {country.count}
                                </Link>
                            </>
                        )}
                    </Typography>
                </Box>
            ))}
        </Box>
        <Typography variant="body2" sx={{ mt: 2.5 }}>
            <Link href="/prayer-times/countries/" underline="hover" sx={{ fontWeight: 600 }}>
                All {cityIndex.countries.length} countries and {TOTAL} cities →
            </Link>
        </Typography>
    </Paper>
);

export default CityDirectory;
